import{_ as a,o as n,c as i,a6 as t}from"./chunks/framework.BrkgobfX.js";const g=JSON.parse('{"title":"19 · MCP 与工具懒加载：接入开放生态，并解决“几百个工具”的规模问题","description":"内置工具写死了，真实用户想接入数据库、浏览器、公司 API，还可能有几百个。讲清 MCP 作为外部工具的标准协议如何让工具生态开放化、任何外部工具如何复用同一个 Tool 抽象，以及“几百个工具塞爆 prompt”怎么用延迟加载 + 工具搜索来解。","frontmatter":{"title":"19 · MCP 与工具懒加载：接入开放生态，并解决“几百个工具”的规模问题","description":"内置工具写死了，真实用户想接入数据库、浏览器、公司 API，还可能有几百个。讲清 MCP 作为外部工具的标准协议如何让工具生态开放化、任何外部工具如何复用同一个 Tool 抽象，以及“几百个工具塞爆 prompt”怎么用延迟加载 + 工具搜索来解。","source":"https://daiw.org/manual/llm-to-agent/mcp"},"headers":[],"relativePath":"manual/agent/llm-to-agent/mcp.md","filePath":"manual/agent/llm-to-agent/mcp.md"}'),e={name:"manual/agent/llm-to-agent/mcp.md"};function l(p,s,o,r,h,c){return n(),i("div",null,[...s[0]||(s[0]=[t(`<h1 id="_19-·-mcp-与工具懒加载-接入开放生态-并解决-几百个工具-的规模问题" tabindex="-1">19 · MCP 与工具懒加载：接入开放生态，并解决“几百个工具”的规模问题 <a class="header-anchor" href="#_19-·-mcp-与工具懒加载-接入开放生态-并解决-几百个工具-的规模问题" aria-label="Permalink to &quot;19 · MCP 与工具懒加载：接入开放生态，并解决“几百个工具”的规模问题&quot;">​</a></h1><blockquote><p>内置工具写死了，真实用户想接入数据库、浏览器、公司 API，还可能有几百个。讲清 MCP 作为外部工具的标准协议如何让工具生态开放化、任何外部工具如何复用同一个 Tool 抽象，以及“几百个工具塞爆 prompt”怎么用延迟加载 + 工具搜索来解。</p></blockquote><p>到目前为止，我们 Agent 的工具都是<strong>内置写死</strong>的。但真实世界里，用户想接入的工具五花八门——查公司数据库、控浏览器、调内部 API、连第三方 SaaS——而且可能有<strong>几百个</strong>。这一篇解决两个问题：<strong>如何开放地接入外部工具</strong>，以及<strong>几百个工具怎么不把 prompt 撑爆</strong>。</p><h2 id="一、背景-内置工具的两道墙" tabindex="-1">一、背景：内置工具的两道墙 <a class="header-anchor" href="#一、背景-内置工具的两道墙" aria-label="Permalink to &quot;一、背景：内置工具的两道墙&quot;">​</a></h2><h3 id="墙一-封闭" tabindex="-1">墙一：封闭 <a class="header-anchor" href="#墙一-封闭" aria-label="Permalink to &quot;墙一：封闭&quot;">​</a></h3><p>内置工具意味着，想加一个新工具，就得改 Agent 的源码、重新发布。用户没法接入<strong>你没预见到的</strong>工具。一个只能用内置工具的 Agent，能力边界被开发者一次性钉死了。</p><h3 id="墙二-规模" tabindex="-1">墙二：规模 <a class="header-anchor" href="#墙二-规模" aria-label="Permalink to &quot;墙二：规模&quot;">​</a></h3><p>就算能动态加工具，还有个规模问题：<a href="/Front2Full/manual/agent/llm-to-agent/prompt-caching">每一轮请求都要把所有工具的 schema 发给模型</a>。十几个工具还好，可要是有<strong>几百个</strong>呢？</p><ul><li><strong>token 爆炸</strong>：几百个工具的完整 schema，可能就是几万 token，每轮重发，又贵又占<a href="/Front2Full/manual/agent/llm-to-agent/token-budget">窗口</a>。</li><li><strong>模型犯晕</strong>：面对几百个工具，模型的选择准确率会下降——太多相似的选项反而让它挑花眼、选错。</li></ul><h2 id="二、解决方案一-mcp-——-外部工具的标准协议" tabindex="-1">二、解决方案一：MCP —— 外部工具的标准协议 <a class="header-anchor" href="#二、解决方案一-mcp-——-外部工具的标准协议" aria-label="Permalink to &quot;二、解决方案一：MCP —— 外部工具的标准协议&quot;">​</a></h2><p><strong>MCP(Model Context Protocol)</strong> 是给“外部工具”定的一套<strong>标准协议</strong>。它的核心思想：</p><blockquote><p><strong>把“工具的提供方”和“Agent”解耦。</strong> 任何人都可以起一个 <strong>MCP 服务器</strong>，用标准协议暴露一组工具/资源；任何 Agent 都可以作为 <strong>MCP 客户端</strong>去连接它、动态发现它有哪些工具、并调用它们——双方事先互不需要了解。</p></blockquote><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─ Agent(MCP 客户端)─┐        ┌─ MCP 服务器(数据库)─┐</span></span>
<span class="line"><span>│  内置工具            │◀─协议─▶│  query_db, list_tables │</span></span>
<span class="line"><span>│  + 发现来的外部工具  │        └────────────────────────┘</span></span>
<span class="line"><span>│                     │        ┌─ MCP 服务器(浏览器)─┐</span></span>
<span class="line"><span>│                     │◀─协议─▶│  navigate, click, read │</span></span>
<span class="line"><span>└─────────────────────┘        └────────────────────────┘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>Agent 启动时连上用户配置的若干 MCP 服务器（本地子进程走 <code>stdio</code> 传输，远端服务走标准化的 <strong>Streamable HTTP</strong> 传输与 OAuth 2.1 授权），<strong>动态发现</strong>它们的工具，把这些工具和内置工具一起，呈现给模型。用户想加能力，只需再连一个 MCP 服务器，<strong>完全不用改 Agent</strong>。</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p><strong>MCP 能这么顺畅地融入，全靠<a href="/Front2Full/manual/agent/llm-to-agent/tool-abstraction">第 04 篇</a>那个 <code>Tool</code> 抽象。</strong> 一个 MCP 工具，和一个内置工具，在 Agent 眼里<strong>长得一模一样</strong>——都是“名字 + 描述 + JSON Schema + 一个 <code>call</code> 方法”。区别只在于：内置工具的 <code>call</code> 是本地函数，MCP 工具的 <code>call</code> 是“把参数按协议发给远端服务器、等结果回来”。<strong>只要把外部工具包装成同一个 <code>Tool</code> 接口，<a href="/Front2Full/manual/agent/llm-to-agent/agent-loop">Agent Loop</a>、<a href="/Front2Full/manual/agent/llm-to-agent/permissions">权限</a>、<a href="/Front2Full/manual/agent/llm-to-agent/streaming-tool-execution">并发编排</a>全都不用改，自动就能驱动它。</strong> 这就是当初把工具设计成一个统一抽象的巨大回报——它让“接入任意外部工具”变成了“实现一个适配器”。</p></div><p>用代码看，接入一个外部工具，就是把它的描述符适配成我们的 <code>Tool</code>：</p><div class="language-ts vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">function</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> externalToolToTool</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">spec</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ExternalToolSpec</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">callRemote</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> CallFn</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Tool</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    name: spec.name,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    description: spec.description,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    schema: </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">jsonSchemaToZod</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(spec.inputSchema),</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    isReadOnly: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, isConcurrencySafe: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, isDestructive: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 外部工具默认保守(fail-closed)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    run</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">async</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">input</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">ctx</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">      const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> result</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> callRemote</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(spec.name, input)   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ← 唯一的区别:call 走远端</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">      return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { modelText: result.text }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><p>包装完，它进入<a href="/Front2Full/manual/agent/llm-to-agent/tool-abstraction">工具注册表</a>，和内置工具平起平坐。<strong>MCP 本质上就是这个适配过程的标准化、协议化版本。</strong></p><h2 id="三、解决方案二-延迟加载-工具搜索" tabindex="-1">三、解决方案二：延迟加载 + 工具搜索 <a class="header-anchor" href="#三、解决方案二-延迟加载-工具搜索" aria-label="Permalink to &quot;三、解决方案二：延迟加载 + 工具搜索&quot;">​</a></h2><p>解决了“接入”，再解决“几百个工具塞爆 prompt”。关键洞察是：</p><blockquote><p><strong>模型在某一轮里，通常只需要几百个工具中的几个。没必要把全部 schema 每轮都塞给它。</strong></p></blockquote><p>于是有了<strong>延迟加载(deferred tools)+ 工具搜索</strong>的机制：</p><ol><li><strong>初始只发工具的“名字 + 一句话简介”</strong>，不发完整 schema。这一下就把几万 token 压到几千。</li><li>提供一个<strong>元工具</strong> <code>search_tools</code>——模型需要某类能力时，用它按关键词搜索，系统才把<strong>匹配到的那几个工具的完整 schema</strong> 加载进上下文。</li><li>模型拿到完整 schema 后，才真正调用它们。</li></ol><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>初始 prompt:  [完整内置工具] + [几百个外部工具:仅名字+简介] + [search_tools 元工具]</span></span>
<span class="line"><span>模型:        search_tools(&quot;数据库 查询&quot;)</span></span>
<span class="line"><span>系统:        → 加载 query_db、list_tables 的完整 schema 进上下文</span></span>
<span class="line"><span>模型:        query_db({ sql: &quot;...&quot; })   ← 现在才有它的完整定义可用</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><div class="info custom-block"><p class="custom-block-title">INFO</p><p>这本质上是把<a href="/Front2Full/manual/agent/llm-to-agent/context-compaction">上下文当缓存、外部当内存的“按需换入”思想</a>用到了<strong>工具</strong>上：工具定义不全量常驻上下文，而是<strong>用到才加载</strong>。它同时解决了 token 爆炸(只加载用到的)和模型犯晕(初始只看到简介、需要时才聚焦到具体几个)两个问题。代价是多一次“搜索”的往返，但换来的是“几百个工具”这个规模下的可用性。</p></div><h2 id="四、小结" tabindex="-1">四、小结 <a class="header-anchor" href="#四、小结" aria-label="Permalink to &quot;四、小结&quot;">​</a></h2><p>这一篇让 Agent 的能力从“开发者钉死的内置集合”变成了“用户可无限扩展的开放生态”：</p><ol><li><strong>MCP</strong> 用标准协议解耦工具提供方与 Agent，让接入外部工具无需改 Agent。</li><li>一切的基础，是<a href="/Front2Full/manual/agent/llm-to-agent/tool-abstraction">第 04 篇那个统一的 <code>Tool</code> 抽象</a>——外部工具只是 <code>call</code> 走远端的普通工具。</li><li><strong>延迟加载 + 工具搜索</strong>解决“几百个工具”的规模问题：按需把工具 schema 换入上下文。</li></ol><p>我们的 Agent 现在几乎无所不能了。但它还缺最后一块，一块让它能“活得久”的东西：<strong>持久化</strong>。到目前为止，一切都在内存里——进程一关，整个会话灰飞烟灭。下一篇，也是本专栏的收官篇，<a href="/Front2Full/manual/agent/llm-to-agent/session-history">会话历史与持久化</a>：如何把这一切落盘，支持关掉再回来接着干。</p><hr><p><strong>本篇对应代码</strong>：配套仓库加入 <code>src/tools/external.ts</code>，演示把一个外部工具描述符适配成统一的 <code>Tool</code> 并动态注册。<code>git checkout article-19</code>。</p>`,31)])])}const d=a(e,[["render",l]]);export{g as __pageData,d as default};
